var i=`0719-maboke`;var n=`world-0719`;var t=`CG`;var s=`central-africa`;var o=4;var r=83;var l={en:`Maboké`,ua:`Мабоке`};var g={en:`Maboké is a Republic of the Congo classic prepared with fish (unspecified), lemon juice, garlic, banana leaf. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мабоке, страва кухні країни Республіка Конго зі складниками: риба (невизначений вид), лимонний сік, часник, банановий лист. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 22 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 22 хвилин.`,t:[`marinating`],m:22,i:[[`fish-unspecified`,720,`g`],[`lemon-juice`,35,`ml`],[`garlic`,4,`clove`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:10,i:[[`banana-leaf`,4,`leaf`],[`tomato`,300,`g`],[`yellow-onion`,210,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`red-palm-oil`,40,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:10,i:[]},{en:`Place leaf-wrapped portions in a steamer over gently boiling water and steam for about 38 minutes until fully cooked; use clean food-safe leaves.`,ua:`Покладіть порції в чистому харчовому листі у пароварку й готуйте над слабко киплячою водою близько 38 хвилин до повної готовності.`,t:[`banana-leaf-steaming`],m:38,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,16,`g`]]}];var c={slug:i,id:n,country:`CG`,region:s,servings:4,minutes:83,title:l,text:g,steps:d};export{t as country,c as default,n as id,r as minutes,s as region,o as servings,i as slug,d as steps,g as text,l as title};